import { PlaywrightCrawler, log } from 'crawlee';
import { chromium } from 'playwright-extra';
import StealthPlugin from 'puppeteer-extra-plugin-stealth';

// 1. AKTIFKAN CLOAK / STEALTH PLUGIN
// Ini akan menyembunyikan fingerprint Playwright, reCAPTCHA v3, Canvas, & WebGL
chromium.use(StealthPlugin());

// Matikan log bawaan Crawlee agar output bersih
log.setLevel(log.LEVELS.OFF);

export async function scrapeChatGPTStealth(promptText) {
    let aiResult = '';

    const crawler = new PlaywrightCrawler({
        headless: true,
        requestHandlerTimeoutSecs: 120, // Mungkin butuh waktu lebih lama untuk ChatGPT
        navigationTimeoutSecs: 60, // Waktu navigasi yang cukup

        launchContext: {
            // Gunakan Launcher Chromium yang sudah dibungkus Stealth/Cloak
            launcher: chromium,
            launchOptions: {
                args: [
                    '--no-sandbox',
                    '--disable-setuid-sandbox',
                    '--disable-dev-shm-usage',
                    '--disable-blink-features=AutomationControlled',
                    '--disable-web-security',
                    '--disable-features=IsolateOrigins,site-per-process'
                ],
            },
            // Chrome User-Agent Asli
            userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36', // User agent yang umum
        },

        async requestHandler({ page }) {
            // 2. Extra Cloaking Injection (Pembersihan flag navigator)
            await page.addInitScript(() => {
                Object.defineProperty(navigator, 'webdriver', { get: () => undefined });
                Object.defineProperty(navigator, 'languages', { get: () => ['en-US', 'en', 'id-ID', 'id'] }); // Sesuaikan bahasa jika perlu
            });

            // Set Header Bahasa (sesuaikan jika perlu)
            await page.setExtraHTTPHeaders({
                'accept-language': 'en-US,en;q=0.9,id-ID;q=0.8,id;q=0.7', // Default bahasa Inggris biasanya lebih aman untuk AI global
            });

            // 3. Buka ChatGPT Web (Pastikan URL benar, bisa berubah)
            // Menggunakan URL chat.openai.com karena ini yang paling umum
            await page.goto('https://chat.openai.com', { waitUntil: 'domcontentloaded' });

            // --- Proses Login atau Skip Login ---
            // ChatGPT seringkali butuh login. Ini bagian yang paling tricky.
            // Kamu mungkin perlu menambahkan logika untuk login otomatis (dengan email/password)
            // atau mendeteksi apakah halaman login muncul dan menanganinya.
            // Untuk contoh ini, kita asumsikan user sudah login atau bisa melewati login.
            // Jika tidak, scraper akan berhenti di sini.
            // PENTING: Menyimpan kredensial login secara aman sangat krusial!
            // Contoh sederhana (JANGAN SIMPAN LANGSUNG DI KODE UNTUK PRODUKSI):
            // try {
            //     const loginButtonSelector = 'button:has-text("Log in")'; // Selector untuk tombol login
            //     await page.waitForSelector(loginButtonSelector, { timeout: 10000 });
            //     await page.click(loginButtonSelector);
            //     await page.fill('input[name="username"]', 'your_email@example.com'); // Ganti dengan email asli
            //     await page.fill('input[name="password"]', 'your_password'); // Ganti dengan password asli
            //     await page.click('button:has-text("Continue")'); // Atau tombol submit login
            //     await page.waitForNavigation({ waitUntil: 'networkidle0' });
            // } catch (error) {
            //     console.log('Login button not found or already logged in.');
            // }
            // --- Akhir Proses Login ---

            // 4. Cari & Isi Input Text
            // Selector ini mungkin perlu disesuaikan karena UI ChatGPT sering berubah
            // Coba cari input field yang punya 'contenteditable' atau 'textarea'
            const inputSelector = 'textarea[placeholder*="Message ChatGPT"], div[contenteditable="true"]';
            await page.waitForSelector(inputSelector, { timeout: 30000 }); // Beri waktu lebih banyak

            // Simulasikan klik & mengetik seperti manusia
            await page.click(inputSelector);
            await page.keyboard.type(promptText, { delay: 50 }); // Sedikit delay agar lebih natural
            await page.waitForTimeout(1000); // Jeda sedikit setelah mengetik

            // Kirim Prompt (biasanya tombol send atau Enter)
            // Selector tombol send bisa berbeda-beda
            const sendButtonSelector = 'button[aria-label="Send message"], button[data-testid="send-button"]'; // Coba selector ini
            await page.waitForSelector(sendButtonSelector, { timeout: 15000 });
            await page.click(sendButtonSelector);

            // 5. Tunggu Respon AI
            // Selector respon AI juga sering berubah. Cari elemen yang menampilkan teks balasan.
            // Ini bisa jadi sangat tricky karena ChatGPT streaming responsnya.
            // Kita perlu menunggu sampai teksnya berhenti muncul atau sampai ada indikator selesai.
            const responseSelector = '.markdown, .message-content'; // Selector umum untuk teks balasan
            await page.waitForSelector(responseSelector, { timeout: 60000 }); // Beri waktu lebih banyak untuk respon streaming

            // Tunggu beberapa detik agar streaming respons selesai
            await page.waitForTimeout(5000); // Jeda 5 detik, mungkin perlu disesuaikan

            // 6. Ekstrak Hasil
            // Ambil teks dari elemen respon terakhir yang muncul
            aiResult = await page.evaluate((sel) => {
                const nodes = document.querySelectorAll(sel);
                if (nodes.length > 0) {
                    // Ambil teks dari elemen terakhir yang berisi balasan
                    return nodes[nodes.length - 1].textContent.trim();
                }
                return '';
            }, responseSelector);
        },
        // Tambahkan error handler jika perlu
        // async handleErrors(error, request) {
        //     console.error(`Request ${request.url} failed: ${error.message}`);
        // }
    });

    // Jalankan crawler untuk URL ChatGPT
    await crawler.run(['https://chat.openai.com']);
    return aiResult;
